import { Injectable, OnDestroy } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { debounceTime } from 'rxjs/operators';

@Injectable()
export class ZoomService implements OnDestroy {
  private zoomMutex = false;
  private _zoom = 1;
  maxZoom = 0;
  minZoom = 0;

  private lastDistance = 0;
  private isPinching = false;
  private ratioX = 0;
  private ratioY = 0;

  private triggerUpdateSizeInternal$ = new BehaviorSubject<void>(undefined);

  // Debounce to prevent rapid-fire updates during continuous zoom
  triggerUpdateSize$ = this.triggerUpdateSizeInternal$.pipe(
    debounceTime(10), // Wait after last zoom before updating
  );

  set zoom(value: number) {
    this._zoom = value;
    this.triggerUpdateSizeInternal$.next();
  }

  get zoom(): number {
    return this._zoom;
  }

  private wheelHandler: ((e: WheelEvent) => void) | null = null;
  private transformWrapper: HTMLElement | null = null;
  private transientScale = 1;

  initSettings(
    container: HTMLElement,
    transformWrapper: HTMLElement,
    isWheelZoom: boolean,
    isWheelCtrlZoom: boolean,
  ): void {
    this.transformWrapper = transformWrapper;
    this.removeListeners(container);

    this.wheelHandler = (e: WheelEvent) => {
      if (isWheelZoom && ((isWheelCtrlZoom && e.ctrlKey) || !isWheelCtrlZoom)) {
        e.preventDefault();
        this.zoomAtCursor(e);
      }
    };

    container.addEventListener('wheel', this.wheelHandler, { passive: false });
    container.addEventListener('touchstart', this.onTouchStart, {
      passive: false,
    });
    container.addEventListener('touchmove', this.onTouchMove, {
      passive: false,
    });
    container.addEventListener('touchend', this.onTouchEnd);
  }

  limitZoom(): void {
    if (this.minZoom === 0 && this.maxZoom === 0) {
      return;
    }

    if (this.maxZoom > 0 && this.zoom > this.maxZoom) {
      this.zoom = this.maxZoom;
    }

    if (this.minZoom > 0 && this.zoom < this.minZoom) {
      this.zoom = this.minZoom;
    }
  }

  private zoomAtCursor(event: WheelEvent): void {
    const ZOOM_STEP = 0.1;
    const delta = event.deltaY < 0 ? 1 + ZOOM_STEP : 1 - ZOOM_STEP;
    this.zoom *= delta;
    this.limitZoom();

    this.triggerUpdateSizeInternal$.next();
  }

  private onTouchStart = (event: TouchEvent): void => {
    if (event.touches.length === 2) {
      event.preventDefault(); // prevent default zoom behavior

      this.isPinching = true;
      this.lastDistance = this.getDistance(event.touches[0], event.touches[1]);
    }
  };

  private onTouchMove = (event: TouchEvent): void => {
    if (this.isPinching && event.touches.length === 2) {
      event.preventDefault();

      const currentDistance = this.getDistance(
        event.touches[0],
        event.touches[1],
      );

      if (this.lastDistance !== 0 && this.transformWrapper) {
        // Calculate the temporary CSS scale relative to the CURRENT library zoom
        this.transientScale = currentDistance / this.lastDistance;

        // Apply CSS transform for native-speed visual feedback
        this.transformWrapper.style.transform = `scale(${this.transientScale})`;
      }
    }
  };

  private onTouchEnd = (event: TouchEvent): void => {
    if (this.isPinching && event.touches.length < 2) {
      event.preventDefault();

      // Finalize the zoom in the library
      if (this.transientScale !== 1) {
        this.zoom *= this.transientScale;
        this.limitZoom();
      }

      // RESET CSS transform so the library can take over rendering
      if (this.transformWrapper) {
        this.transformWrapper.style.transform = 'scale(1)';
      }

      this.isPinching = false;
      this.lastDistance = 0;
      this.transientScale = 1;
    }
  };

  private getDistance(touch1: Touch, touch2: Touch): number {
    const dx = touch2.clientX - touch1.clientX;
    const dy = touch2.clientY - touch1.clientY;

    return Math.hypot(dx, dy);
  }

  saveScrollPosition(container: HTMLElement): void {
    if (this.zoomMutex) {
      return;
    }

    this.zoomMutex = true;

    const { scrollLeft, scrollTop, scrollWidth, scrollHeight } = container;
    const { width, height } = container.getBoundingClientRect();

    const centerX = scrollLeft + width / 2;
    const centerY = scrollTop + height / 2;

    this.ratioX = centerX / scrollWidth;
    this.ratioY = centerY / scrollHeight;
  }

  restoreScrollPosition(container: HTMLElement): void {
    requestAnimationFrame(() => {
      const { width, height } = container.getBoundingClientRect();

      const centerX = this.ratioX * container.scrollWidth;
      const centerY = this.ratioY * container.scrollHeight;

      container.scrollLeft = centerX - width / 2;
      container.scrollTop = centerY - height / 2;

      this.zoomMutex = false;
    });
  }

  removeListeners(container: HTMLElement): void {
    if (!container) {
      return;
    }

    if (this.wheelHandler) {
      container.removeEventListener('wheel', this.wheelHandler);
      this.wheelHandler = null;
    }

    container.removeEventListener('touchstart', this.onTouchStart);
    container.removeEventListener('touchmove', this.onTouchMove);
    container.removeEventListener('touchend', this.onTouchEnd);
  }

  ngOnDestroy(): void {
    this.triggerUpdateSizeInternal$.complete();
  }
}
